contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address player) public payable {
        require(true);

        bool before = c.hasPlayerWagered(player); if (__ESBMC_reverted()) return;

        bool after_ = c.hasPlayerWagered(player); if (__ESBMC_reverted()) return;

        assert(after_ == before);
    }

    receive() external payable {}
}

