pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(address player) internal {
        vm.assume(true);
        bool before;
        try c.hasPlayerWagered(player) returns (bool __r) { before = __r; } catch { return; }
        bool after_;
        try c.hasPlayerWagered(player) returns (bool __r) { after_ = __r; } catch { return; }
        assertTrue(after_ == before);
    }

    function testFuzz_run(address player) public {
        vm.assume(player.code.length == 0 && uint160(player) > 0xffff && player != address(this) && player != address(c) && player != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && player != 0x000000000000000000636F6e736F6c652e6c6f67 && player != 0x4e59b44847b379578588920cA78FbF26c0B4956C && player != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(player);
    }

    receive() external payable {}
}
